/* Hilfsfunktionen für die Schiffsgarten-Abschnitte (nur Darstellung, keine Inhalte) */
window.SG = {
 E: function(n){ return n === 0 ? "Gratis" : n === 1 ? "1 Einsatz" : n + " Einsätze"; },
 pflanze: function(w){
  var kopf = w.viertel + "/4 · " + (w.leiste ? w.leiste + "er-Leiste · " : "") + w.typ + (w.sek ? " (" + w.sek + ")" : "");
  var t = kopf + "\n" + w.text;
  if(w.ernte) t += "\nErnte: " + w.ernte.join(", ");
  if(w.effekt) t += "\nBesondere Eigenschaften: " + w.effekt;
  return {c:w.name, x:t};
 },
 pflanzenGruppe: function(g){ return window.WS_GARTEN.filter(function(w){ return w.gruppe === g; }).map(window.SG.pflanze); },
 beet: function(b, extra){
  var c = {c:b.name + " · " + window.SG.E(b.kosten) + (extra ? " · " + extra : ""), x:b.text};
  if(b.regeln && b.regeln.length) c.l = b.regeln; return c;
 },
 beete: function(art){ return window.WS_GARTEN_BEETE.filter(function(b){ return b.art === art; }).map(function(b){ return window.SG.beet(b); }); },
 byId: function(id){ return window.WS_GARTEN.filter(function(w){ return w.id === id; })[0]; }
};
